import React, { useEffect, useState, useRef } from "react";



import { getStore, updStore, gen16CodeId,  ObjectKeys, downloadCSVFromJson, convertObj2Array} from "../../../stores/Utils";

import {CheckBoxSlide_Cmpt, SearchInput_Cmpt } from "../../../components";

import { OpenModal } from "../../../components/DialogHRM";

import "./dashboard.css"
import { AddEmployee_Cmpt, EmployeeItem_Cmpt } from "..";
import {  get_filter_paystub, get_filter_paystubAsync, getall_employee, parseTimeClock, search_employee } from "../services/server_fetching";
import { get_balances_by_type } from "../../CuentasContables/services/server_fetching";
import { SumBalanceItm, SumBalancePS } from "./ViewPayStubMayor";
import { DateCalComponent_Cmpt } from "../../Inventory";
import { OpenToast } from "../../../components/Toast";



const CheckBoxSlide = CheckBoxSlide_Cmpt();
const SearchInput = SearchInput_Cmpt();
const AddEmployee = AddEmployee_Cmpt();
const DateCalComponent = DateCalComponent_Cmpt();


const EmployeeItem = EmployeeItem_Cmpt();



const EmployeeDashboard  = ({ data, elmId, updObs }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);

	const [filter, setFilter] = useState(false);
	const [loading, set_loading] = useState(false);




	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			set_obs(gen16CodeId())
			get_balances_by_type("global_accounts","global_account_params",handle_getall_employee);
			updStore("cmpByPayStubMayor",{})
			
		}
	});






	const openSubMayor = async (pp) => {
		let empl = {}
		OpenToast({ text: "Generarando reporte de pago ", timeout: 1500 });
		let hus = await get_filter_paystubAsync();
		hus && ObjectKeys(hus).map(cid=>{
			let emplId = hus[cid]?.employeeId;
			if(!getStore("employees_ids")?.[emplId]?.hasW2){
				empl[emplId] ={ payTo:  getStore("employees_ids")?.[emplId]?.name, netPay: SumBalanceItm(hus[cid]).toFixed(2)};
			}
		})
		let nArr = convertObj2Array(empl);
		if(nArr.length>0){
			downloadCSVFromJson(`export_payroll_${pp}_${gen16CodeId()}.csv`,nArr);
		}else{
			OpenToast({ text: "No se pudo generar el reporte", timeout: 1500 });
     	}
		
	}






	const openAddView =  () => {
		
		let data = {};
		data["zIndex"] = 450;
		data["height"] = "80vh";
		// data['observeResize']=true;
		data["props"] = { minHeight: "1vh", overlay: true };
		data["content"] = 
			<AddEmployee confimr={handle_getall_employee} />
		OpenModal(data);
	}


	

	const handleChange =  (v) => {
		!loading && set_loading(true)
	}


	const handle_search_employee =  (v) => {
		set_loading(true)
		search_employee(cb_result)
	}


	const handle_getall_employee =  (v) => {
		getall_employee(cb_result)
	}

	const cb_result = async (f, v) => {
		set_obs(gen16CodeId())
		set_loading(false);
	};


	
	const setPeriod2Sum = async ( v) => {
		updStore("datePeriodRs",v)
		set_obs(gen16CodeId())
		openSubMayor(v);
	};

	const setEmployeeOut = async ( v) => {
		updStore("employeeOut",v)
		getall_employee(cb_result)
	};

	

	return (

	<div className="">
		<div className="accounts_header">
			<h2>Empleados</h2>
			<div className="_dsplFlx ">
				<div className="centerBx">
					<p className="group_title addBtn purple" onClick={openAddView} style={{margin: 0}}>
						Agregar Empleado
					</p>
				</div>
				<div className="_dsplFlx centerBx" >
					<span className={`checklabel`}>
						{"All"}
					</span>
					<CheckBoxSlide
						initvalue={getStore("employeeOut")}
						keyCode={57}
						updChange={(e)=>setEmployeeOut(e)}
					/>
				</div>
				<div className="flexSpace"/>
				<div style={{margin:"14px 10px 0px 0"}}>
					<DateCalComponent  
						init={getStore("datePeriodRs")} 
						label={"Exportar Periodo de Pago"}
						updDate={(e)=>setPeriod2Sum(e)}
					/>
				</div>
			</div>
			<div className="_dsplFlx " style={{marginTop:14}}>
				<SearchInput
						placeholder={"Buscar ...."} 
						width={360}
						obs={set_obs}
						fetchData={handle_search_employee}
						loading={loading}
						change={handleChange}
						callempty={handle_getall_employee}
						keyFlds={"searchQry"}
					/>
				<div className="flexSpace"/>
				<div className="_dsplFlx ">
					<div className="total_comprobante_title" >
						No de Empleados: 
					</div>
					<div className="total_comprobante gray">
						<span>
							{ObjectKeys(getStore("employees_list"))?.length}
						</span>
					</div>
					
				</div>
			</div>
		</div>

		

		
			<div className="employees_container scollVh">
				{getStore("employees_list") && ObjectKeys(getStore("employees_list"))?.map(cid=>{
					return (
						<EmployeeItem 
							data={getStore("employees_list")[cid]} 
							elmId={cid} 
							key={cid}
							
							handleRefreshAll={handle_getall_employee}
						/>
					)
				})}
			</div>
		
		</div>
	);
};

export default EmployeeDashboard;
